<script setup>
import {ref,computed,onMounted} from 'vue';import {supabase} from '../services/supabase';import AppShell from '../components/AppShell.vue';import {RouterLink} from 'vue-router';
const jobs=ref([]),loading=ref(true),search=ref(''),type=ref('all'),location=ref(''),error=ref('');const filtered=computed(()=>jobs.value.filter(j=>(type.value==='all'||j.job_type===type.value)&&(!location.value||j.location?.toLowerCase().includes(location.value.toLowerCase()))&&(!search.value||`${j.title} ${j.description} ${j.category} ${j.company_name}`.toLowerCase().includes(search.value.toLowerCase()))));async function load(){loading.value=true;const {data,error:e}=await supabase.from('jobs').select('*, employer:profiles!jobs_employer_id_fkey(full_name,company_name)').eq('status','active').order('created_at',{ascending:false});if(e)error.value=e.message;jobs.value=(data||[]).map(j=>({...j,company_name:j.employer?.company_name||j.employer?.full_name||'Local employer',verified:j.employer?.verification_status==='verified'}));loading.value=false}onMounted(load)
</script>
<template><AppShell title="Find jobs" subtitle="Discover work that fits your schedule"><template #default><div class="page-heading"><div><span class="eyebrow">OPPORTUNITY BOARD</span><h1 class="page-title">Find your next gig.</h1><p class="page-subtitle">Explore student-friendly opportunities and take your next step.</p></div><RouterLink to="/saved" class="btn btn-outline">♡ Saved jobs</RouterLink></div><div class="search-panel card"><input v-model="search" class="input" placeholder="Search job title, skills or keyword…"><input v-model="location" class="input" placeholder="Location / campus"><select v-model="type" class="input"><option value="all">All job types</option><option>Part-time</option><option>Casual</option><option>Internship</option><option>Freelance</option><option>Once-off</option><option>Tutoring</option></select></div><div class="results-line"><b>{{filtered.length}} opportunities</b><span class="muted">Newest opportunities first</span></div><div v-if="loading" class="empty">Loading jobs…</div><div v-else-if="error" class="alert error">{{error}}</div><div v-else-if="filtered.length" class="grid grid-3"><RouterLink v-for="job in filtered" :key="job.id" :to="`/jobs/${job.id}`" class="card job-card"><div class="job-meta"><span class="badge green">{{job.job_type}}</span><span>{{job.location||'Flexible location'}}</span></div><h3>{{job.title}}</h3><p>{{job.company_name}} <span v-if="job.verified" class="verified">✓ Verified</span> · {{job.category||'General'}}</p><p>{{job.description?.slice(0,135)}}{{job.description?.length>135?'…':''}}</p><div class="job-card-foot"><b>{{job.pay_amount?`R${job.pay_amount}${job.pay_period==='hourly'?'/hr':job.pay_period==='monthly'?'/mo':''}`:'Pay discussed'}}</b><span class="muted">Details →</span></div></RouterLink></div><div v-else class="empty"><div style="font-size:35px">⌕</div><h3>No matching opportunities</h3><p>Try another keyword, location or job type.</p><button class="btn btn-outline" @click="search='';location='';type='all'">Clear filters</button></div></template></AppShell></template>
<style scoped>.page-heading{display:flex;justify-content:space-between;align-items:end;gap:15px}.search-panel{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px;margin:22px 0}.results-line{display:flex;justify-content:space-between;margin:22px 0 14px;font-size:13px}.job-card{min-height:225px}.job-card p:nth-of-type(1){font-weight:700;color:var(--text)}.verified{display:inline-block;background:#dcfce7;color:#166534;border-radius:20px;padding:2px 6px;font-size:10px}@media(max-width:700px){.search-panel{grid-template-columns:1fr}.page-heading{align-items:start;flex-direction:column}}</style>
